let csrfToken = '';
let invoiceCommercialSource = null;
const taxRates = { '00': 0, '01': 0.07, '02': 0.10, '03': 0.15 };
async function request(url, options = {}) { const response = await fetch(url, { credentials: 'same-origin', ...options }); const data = await response.json(); if (!response.ok) { const error = new Error(data.error || 'Solicitud fallida.'); error.details = data.details; error.code = data.code; error.status = data.status; throw error; } return data; }
function articleOptions(selected=''){return '<option value="">Entrada manual</option>'+articleCatalog.map(article=>`<option value="${article.id}" ${String(article.id)===String(selected)?'selected':''}>${escapeHtml(article.name)}${article.sku?` · ${escapeHtml(article.sku)}`:''} (${article.itemType==='service'?'Servicio':'Producto'})</option>`).join('');}
function applyArticleToRow(row,article){if(!article)return;row.querySelector('[data-field="description"]').value=article.description||article.name;row.querySelector('[data-field="code"]').value=article.sku||'';row.querySelector('[data-field="unitPrice"]').value=Number(article.salePrice).toFixed(2);row.querySelector('[data-field="taxCode"]').value=article.taxCode;calculate();}
function addItem(articleId='') { const fragment = document.querySelector('#item-template').content.cloneNode(true); const select=fragment.querySelector('[data-article-select]');select.innerHTML=articleOptions(articleId);select.addEventListener('change',()=>{const row=select.closest('.invoice-item'),article=articleCatalog.find(item=>String(item.id)===select.value);if(article)applyArticleToRow(row,article);}); fragment.querySelector('.remove-item').addEventListener('click', (event) => { if (document.querySelectorAll('.invoice-item').length > 1) event.currentTarget.closest('.invoice-item').remove(); calculate(); }); fragment.querySelectorAll('input,select').forEach((element) => element.addEventListener('input', calculate)); document.querySelector('#items').append(fragment);if(articleId)applyArticleToRow(document.querySelector('#items').lastElementChild,articleCatalog.find(item=>String(item.id)===String(articleId))); calculate(); }
function items() { return [...document.querySelectorAll('.invoice-item')].map((row) => Object.fromEntries([...row.querySelectorAll('[data-field]')].map((input) => [input.dataset.field, input.value]))); }
function taxBreakdown(lines){const result={'00':{base:0,tax:0},'01':{base:0,tax:0},'02':{base:0,tax:0},'03':{base:0,tax:0}};for(const item of lines){const code=Object.hasOwn(result,item.taxCode)?item.taxCode:'00',net=Math.round((Number(item.quantity)||0)*(Number(item.unitPrice)||0)*100)/100;result[code].base+=net;result[code].tax+=Math.round(net*(taxRates[code]||0)*100)/100;}return result;}
function calculate(){const breakdown=taxBreakdown(items());let total=0;for(const [code,amounts] of Object.entries(breakdown)){amounts.base=Math.round(amounts.base*100)/100;amounts.tax=Math.round(amounts.tax*100)/100;total+=amounts.base+amounts.tax;const base=document.querySelector(`[data-tax-base="${code}"]`),tax=document.querySelector(`[data-tax-amount="${code}"]`);if(base)base.textContent=`B/. ${amounts.base.toFixed(2)}`;if(tax)tax.textContent=code==='00'?'—':`B/. ${amounts.tax.toFixed(2)}`;}document.querySelector('#grand-total').textContent=`B/. ${total.toFixed(2)}`;}
function formPayload(form) { const payload = Object.fromEntries(new FormData(form)); payload.items = items(); if(invoiceCommercialSource)Object.assign(payload,invoiceCommercialSource); return payload; }
function escapeHtml(value) { const node = document.createElement('span'); node.textContent = String(value ?? ''); return node.innerHTML; }
async function loadInvoices() { const { invoices } = await request('/api/invoices'); const list = document.querySelector('#invoice-list'); list.innerHTML = invoices.length ? invoices.map((invoice) => `<article class="invoice-history"><div><strong>${escapeHtml(invoice.fiscalNumber)}</strong><span>${escapeHtml(invoice.customerName || 'Consumidor final')}</span></div><div><strong>B/. ${Number(invoice.total).toFixed(2)}</strong><span class="status status-${escapeHtml(invoice.status)}">${escapeHtml(invoice.status)}</span></div>${invoice.qr ? `<a href="${escapeHtml(invoice.qr)}" target="_blank" rel="noopener">Consultar QR</a>` : ''}${invoice.status === 'uncertain' ? `<button data-refresh="${invoice.id}" type="button">Consultar estado</button>` : ''}</article>`).join('') : '<p class="subtitle">No hay documentos emitidos.</p>'; list.querySelectorAll('[data-refresh]').forEach((button) => button.addEventListener('click', async () => { button.disabled = true; try { await request(`/api/invoices/${button.dataset.refresh}/refresh`, { method: 'POST', headers: { 'x-csrf-token': csrfToken } }); await loadInvoices(); } catch (error) { alert(error.message); } finally { button.disabled = false; } })); }
async function stepUpMfa(code) { return request('/api/auth/mfa/step-up', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken }, body: JSON.stringify({ code }) }); }
async function secureConfigAction(action, form) { try { return await action(); } catch (error) { if (error.code !== 'MFA_RECENT_REQUIRED') throw error; const code = form.elements.mfaCode.value.trim(); if (!/^\d{6}$/.test(code)) { form.querySelector('.config-mfa').hidden = false; form.elements.mfaCode.focus(); throw new Error('Introduce tu código MFA actual para autorizar esta operación.'); } await stepUpMfa(code); form.elements.mfaCode.value = ''; form.querySelector('.config-mfa').hidden = true; return action(); } }
function configurationMarkup() { return `<section id="fiscal-config" class="configuration-panel"><div class="config-heading"><div><span class="eyebrow">Zero Trust</span><h2>Integración fiscal</h2><p>Configura The Factory HKA. Demo y producción autentican la API con credenciales propias del ambiente seleccionado.</p></div><span id="config-status" class="config-status">Consultando…</span></div><form id="fiscal-config-form" autocomplete="off"><div class="form-grid"><div class="field"><label for="config-environment">Ambiente</label><select id="config-environment" name="environment"><option value="demo">Demo · sin validez fiscal</option><option value="production">Producción · documentos fiscales válidos</option></select></div><div class="field"><label for="config-branch">Sucursal</label><input id="config-branch" name="branchCode" maxlength="4" value="0000" required></div><div class="field"><label for="config-branch-type">Tipo de sucursal</label><select id="config-branch-type" name="branchType"><option value="1">1 · Venta al detal</option><option value="2">2 · Venta al por mayor</option></select></div><div class="field"><label for="config-point">Punto de facturación</label><input id="config-point" name="billingPoint" inputmode="numeric" pattern="[0-9]{3}" maxlength="3" value="001" required></div><div class="field"><label for="config-timeout">Timeout (ms)</label><input id="config-timeout" name="timeoutMs" type="number" min="1000" max="120000" value="30000" required></div></div><div class="config-secret-box"><div><strong>Credenciales del ambiente seleccionado</strong><p>Usuario y contraseña son obligatorios en ambos ambientes, se reemplazan juntos y nunca pueden recuperarse desde el navegador.</p></div><div class="form-grid"><div class="field"><label for="config-username">Usuario de servicios web HKA</label><input id="config-username" name="username" maxlength="200" autocomplete="off" required></div><div class="field"><label for="config-password">Contraseña de servicios web HKA</label><input id="config-password" name="password" type="password" maxlength="500" autocomplete="new-password" required></div></div></div><div class="config-mfa" hidden><label for="config-mfa-code">Confirmación MFA</label><input id="config-mfa-code" name="mfaCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000"></div><p class="form-message" role="alert" aria-live="polite"></p><div class="config-actions"><button id="test-fiscal-config" class="small-button" type="button">Probar configuración guardada</button><button class="submit-button" type="submit">Guardar ambiente y credenciales</button></div></form></section>`; }
async function loadConfiguration(form) { const status = await request('/api/config/fiscal-api'); form.elements.environment.value = status.environment; form.elements.branchCode.value = status.branchCode; form.elements.branchType.value = status.branchType; form.elements.billingPoint.value = status.billingPoint; form.elements.timeoutMs.value = status.timeoutMs; const badge = document.querySelector('#config-status'); badge.textContent = status.configured ? 'Configurado' : 'No configurado'; badge.className = `config-status ${status.configured ? 'configured' : ''}`; }
async function mountConfiguration() { document.querySelector('#configuration-host').innerHTML = configurationMarkup(); const form = document.querySelector('#fiscal-config-form'); const message = form.querySelector('.form-message'); const show = (kind, value) => { message.className = `form-message ${kind}`; message.textContent = value; }; form.addEventListener('submit', async (event) => { event.preventDefault(); if (!form.reportValidity()) return; const button = form.querySelector('[type="submit"]'); button.disabled = true; show('', ''); try { const payload = Object.fromEntries(new FormData(form)); delete payload.mfaCode; const action = () => request('/api/config/fiscal-api', { method: 'PUT', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken }, body: JSON.stringify(payload) }); await secureConfigAction(action, form); form.elements.username.value = ''; form.elements.password.value = ''; show('success', 'Configuración cifrada y actualizada.'); await loadConfiguration(form); } catch (error) { show('error', [error.message, ...(error.details || [])].join(' ')); } finally { button.disabled = false; } }); document.querySelector('#test-fiscal-config').addEventListener('click', async (event) => { event.currentTarget.disabled = true; show('', ''); try { const action = () => request('/api/config/fiscal-api/test', { method: 'POST', headers: { 'x-csrf-token': csrfToken } }); const result = await secureConfigAction(action, form); show('success', result.message); } catch (error) { show('error', error.message); } finally { event.currentTarget.disabled = false; } }); await loadConfiguration(form); }
let clientFields = [];
let isAdministrator = false;
function customerTypeLabel(type) { return ({ '01': 'Contribuyente', '02': 'Consumidor final', '03': 'Gobierno', '04': 'Extranjero' })[type] || type; }
function setClientTaxVisibility() { const form = document.querySelector('#client-form'); const type = form.elements.customerType.value; const foreign = type === '04'; form.querySelectorAll('.foreign-field').forEach((field) => { field.hidden = !foreign; }); form.querySelectorAll('.domestic-field').forEach((field) => { field.hidden = !['01', '03'].includes(type); }); if (foreign && form.elements.countryCode.value === 'PA') form.elements.countryCode.value = ''; form.querySelector('.country-other').hidden = form.elements.countryCode.value.toUpperCase() !== 'ZZ'; }
function renderCustomFields(values = {}) { const host = document.querySelector('#custom-fields'); host.innerHTML = clientFields.length ? clientFields.map((field) => { const value = values[field.id] ?? ''; const required = field.isRequired ? 'required' : ''; if (field.fieldType === 'boolean') return `<div class="field"><label>${escapeHtml(field.label)}</label><select name="custom_${field.id}" ${required}><option value="">Sin definir</option><option value="true" ${value === 'true' ? 'selected' : ''}>Sí</option><option value="false" ${value === 'false' ? 'selected' : ''}>No</option></select></div>`; return `<div class="field"><label>${escapeHtml(field.label)}${field.isRequired ? ' *' : ''}</label><input name="custom_${field.id}" type="${field.fieldType}" value="${escapeHtml(value)}" ${required}></div>`; }).join('') : '<p class="subtitle wide">Aún no hay campos personalizados definidos.</p>'; }
async function loadClientFields() { const result = await request('/api/clients/custom-fields'); clientFields = result.fields; renderCustomFields(); }
async function loadClients(search = '') { const { clients } = await request(`/api/clients?search=${encodeURIComponent(search)}`); const list = document.querySelector('#client-list'); list.innerHTML = clients.length ? clients.map((client) => `<button class="client-list-item" type="button" data-client-id="${client.id}"><strong>${escapeHtml(client.legalName)}</strong><span>${escapeHtml(customerTypeLabel(client.customerType))}${client.ruc ? ` · RUC ${escapeHtml(client.ruc)}-${escapeHtml(client.dv || '')}` : ''}</span></button>`).join('') : '<p class="subtitle" style="padding:18px">No se encontraron clientes.</p>'; list.querySelectorAll('[data-client-id]').forEach((button) => button.addEventListener('click', () => editClient(button.dataset.clientId))); const select = document.querySelector('#invoice-client'); const selected = select.value; select.innerHTML = '<option value="">Factura sin ficha vinculada</option>' + clients.map((client) => `<option value="${client.id}">${escapeHtml(client.legalName)}${client.ruc ? ` · ${escapeHtml(client.ruc)}` : ''}</option>`).join(''); select.value = selected; }
function openClientForm() { document.querySelector('#client-empty').hidden = true; const form = document.querySelector('#client-form'); form.hidden = false; document.querySelector('#client-message').textContent = ''; }
function newClient() { const form = document.querySelector('#client-form'); form.reset(); form.elements.id.value = ''; form.elements.status.value = 'active'; form.elements.customerType.value = '02'; form.elements.countryCode.value = 'PA'; document.querySelector('#client-form-title').textContent = 'Nuevo cliente'; renderCustomFields(); setClientTaxVisibility(); openClientForm(); }
async function editClient(id) { const { client } = await request(`/api/clients/${id}`); const form = document.querySelector('#client-form'); form.reset(); Object.entries(client).forEach(([key, value]) => { if (form.elements[key] && key !== 'customFields') form.elements[key].value = value ?? ''; }); document.querySelector('#client-form-title').textContent = client.legalName; document.querySelector('#client-state').textContent = client.status === 'active' ? 'Activo' : 'Inactivo'; renderCustomFields(client.customFields); setClientTaxVisibility(); openClientForm(); }
function clientPayload(form) { const payload = Object.fromEntries(new FormData(form)); payload.customFields = {}; for (const [key, value] of Object.entries(payload)) if (key.startsWith('custom_')) { payload.customFields[key.slice(7)] = value; delete payload[key]; } return payload; }
async function selectInvoiceClient(id) { if (!id) return; const { client } = await request(`/api/clients/${id}`); const form = document.querySelector('#invoice-form'); const mapping = { customerType: 'customerType', legalName: 'customerName', email: 'customerEmail', phone: 'phone', contributorType: 'contributorType', ruc: 'ruc', dv: 'dv', address: 'address', locationCode: 'locationCode', province: 'province', district: 'district', township: 'township', countryCode: 'countryCode', countryOther: 'countryOther', foreignIdType: 'foreignIdType', foreignIdNumber: 'foreignIdNumber', foreignCountry: 'foreignCountry' }; Object.entries(mapping).forEach(([source, target]) => { if (form.elements[target]) form.elements[target].value = client[source] ?? ''; }); document.querySelector('#taxpayer-fields').hidden = !['01', '03'].includes(client.customerType); }
function setupClients() { const form = document.querySelector('#client-form'); document.querySelector('#new-client').addEventListener('click', newClient); document.querySelector('#open-client-from-invoice').addEventListener('click', () => { navigate('clients'); newClient(); }); document.querySelector('#cancel-client').addEventListener('click', () => { form.hidden = true; document.querySelector('#client-empty').hidden = false; }); document.querySelector('#client-search').addEventListener('input', (event) => loadClients(event.target.value).catch(() => {})); form.elements.customerType.addEventListener('change', setClientTaxVisibility); form.elements.countryCode.addEventListener('input', setClientTaxVisibility); document.querySelector('#invoice-client').addEventListener('change', (event) => selectInvoiceClient(event.target.value)); document.querySelectorAll('[data-client-tab]').forEach((button) => button.addEventListener('click', () => { document.querySelectorAll('[data-client-tab]').forEach((item) => item.classList.toggle('active', item === button)); document.querySelectorAll('[data-client-panel]').forEach((panel) => { panel.hidden = panel.dataset.clientPanel !== button.dataset.clientTab; panel.classList.toggle('active', !panel.hidden); }); })); form.addEventListener('submit', async (event) => { event.preventDefault(); const message = document.querySelector('#client-message'); const payload = clientPayload(form); const id = payload.id; delete payload.id; try { const result = await request(id ? `/api/clients/${id}` : '/api/clients', { method: id ? 'PUT' : 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken }, body: JSON.stringify(payload) }); message.className = 'form-message success'; message.textContent = result.message; form.elements.id.value = result.id; await loadClients(document.querySelector('#client-search').value); } catch (error) { message.className = 'form-message error'; message.textContent = [error.message, ...(error.details || [])].join(' '); } }); document.querySelector('#add-custom-field').addEventListener('click', async () => { const label = document.querySelector('#custom-field-label').value; const fieldType = document.querySelector('#custom-field-type').value; if (!label.trim()) return; await request('/api/clients/custom-fields', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken }, body: JSON.stringify({ label, fieldType }) }); document.querySelector('#custom-field-label').value = ''; await loadClientFields(); }); }
let articleFilter = '', articleCatalog = [], quickArticleTarget = null;
async function loadInvoiceArticleCatalog(selectedId=''){const {articles}=await request('/api/articles');articleCatalog=articles;document.querySelectorAll('[data-article-select]').forEach(select=>{const current=selectedId||select.value;select.innerHTML=articleOptions(current);if(selectedId&&select.closest('.invoice-item')===quickArticleTarget)select.value=String(selectedId);});}
async function loadArticles() { const search=document.querySelector('#article-search').value; const {articles}=await request(`/api/articles?search=${encodeURIComponent(search)}&type=${articleFilter}`); const host=document.querySelector('#article-list'); host.innerHTML=articles.length?articles.map(a=>`<button class="client-list-item" type="button" data-article-id="${a.id}"><strong>${escapeHtml(a.name)}</strong><span class="article-kind">${a.itemType==='service'?'Servicio':'Producto'}</span><span>${escapeHtml(a.sku||'Sin SKU')} · B/. ${Number(a.salePrice).toFixed(2)}</span></button>`).join(''):'<p class="subtitle" style="padding:18px">No se encontraron artículos.</p>'; host.querySelectorAll('[data-article-id]').forEach(b=>b.addEventListener('click',()=>editArticle(b.dataset.articleId))); }
function newArticle(){const form=document.querySelector('#article-form');form.reset();form.elements.id.value='';form.elements.itemType.value='product';form.elements.status.value='active';form.elements.unit.value='und';form.elements.currency.value='USD';form.elements.taxCode.value='00';document.querySelector('#article-form-title').textContent='Nuevo artículo';document.querySelector('#article-empty').hidden=true;form.hidden=false;}
async function editArticle(id){const {article}=await request(`/api/articles/${id}`);const form=document.querySelector('#article-form');form.reset();Object.entries(article).forEach(([k,v])=>{if(form.elements[k]&&k!=='availableInPos')form.elements[k].value=v??'';});form.elements.availableInPos.checked=Boolean(article.availableInPos);document.querySelector('#article-form-title').textContent=article.name;document.querySelector('#article-empty').hidden=true;form.hidden=false;}
function articleImportData(confirm=false){const data=new FormData(),file=document.querySelector('#article-file').files[0];if(file)data.append('file',file);if(confirm)data.append('confirm','true');return data;}
function articlePreview(data){const s=data.summary,rows=data.preview.map(r=>`<div class="import-row"><span>Fila ${r.row}</span><strong>${escapeHtml(r.name)}</strong><span>${r.itemType==='service'?'Servicio':'Producto'} · B/. ${Number(r.salePrice).toFixed(2)}</span></div>`).join('');return `<div class="import-summary"><div><strong>${s.total}</strong><span>Total</span></div><div><strong>${s.products}</strong><span>Productos</span></div><div><strong>${s.services}</strong><span>Servicios</span></div><div><strong>${s.duplicates+s.invalid}</strong><span>Omitidos</span></div></div><div class="import-rows">${rows}</div>`;}
function setupArticles(){const form=document.querySelector('#article-form'),dialog=document.querySelector('#article-import-dialog'),importForm=document.querySelector('#article-import-form'),message=document.querySelector('#article-import-message'),confirm=document.querySelector('#confirm-article-import');document.querySelector('#new-article').addEventListener('click',newArticle);document.querySelector('#cancel-article').addEventListener('click',()=>{form.hidden=true;document.querySelector('#article-empty').hidden=false;});document.querySelector('#article-search').addEventListener('input',()=>loadArticles().catch(()=>{}));document.querySelectorAll('[data-article-filter]').forEach(button=>button.addEventListener('click',()=>{articleFilter=button.dataset.articleFilter;document.querySelectorAll('[data-article-filter]').forEach(x=>x.classList.toggle('active',x===button));loadArticles();}));form.addEventListener('submit',async event=>{event.preventDefault();const payload=Object.fromEntries(new FormData(form)),id=payload.id;delete payload.id;const msg=document.querySelector('#article-message');try{const result=await request(id?`/api/articles/${id}`:'/api/articles',{method:id?'PUT':'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(payload)});msg.className='form-message success';msg.textContent=result.message;form.elements.id.value=result.id;await loadArticles();}catch(error){msg.className='form-message error';msg.textContent=[error.message,...(error.details||[])].join(' ');}});const close=()=>{dialog.close();importForm.reset();document.querySelector('#article-import-preview').innerHTML='';confirm.hidden=true;message.textContent='';};document.querySelector('#import-articles').addEventListener('click',()=>dialog.showModal());document.querySelector('#close-article-import').addEventListener('click',close);document.querySelector('#cancel-article-import').addEventListener('click',close);importForm.addEventListener('submit',async event=>{event.preventDefault();if(!importForm.reportValidity())return;message.textContent='Analizando archivo…';try{const data=await request('/api/articles/import/zoho',{method:'POST',headers:{'x-csrf-token':csrfToken},body:articleImportData()});document.querySelector('#article-import-preview').innerHTML=articlePreview(data);confirm.hidden=data.summary.ready===0;message.textContent=`${data.summary.ready} artículos listos; ${data.summary.duplicates} duplicados y ${data.summary.invalid} inválidos serán omitidos.`;}catch(error){message.className='form-message error';message.textContent=error.message;}});confirm.addEventListener('click',async()=>{confirm.disabled=true;try{const data=await request('/api/articles/import/zoho',{method:'POST',headers:{'x-csrf-token':csrfToken},body:articleImportData(true)});message.className='form-message success';message.textContent=data.message;confirm.hidden=true;await loadArticles();}catch(error){message.className='form-message error';message.textContent=error.message;}finally{confirm.disabled=false;}});}
function setupQuickArticle(){const dialog=document.querySelector('#quick-article-dialog'),form=document.querySelector('#quick-article-form'),message=form.querySelector('.form-message');const close=()=>{dialog.close();form.reset();form.elements.status.value='active';form.elements.currency.value='USD';form.elements.unit.value='und';message.textContent='';};document.querySelector('#quick-create-article').addEventListener('click',()=>{quickArticleTarget=document.querySelector('#items').lastElementChild;if(!quickArticleTarget){addItem();quickArticleTarget=document.querySelector('#items').lastElementChild;}dialog.showModal();});document.querySelector('#close-quick-article').addEventListener('click',close);document.querySelector('#cancel-quick-article').addEventListener('click',close);form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('[type="submit"]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(form));const result=await request('/api/articles',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(payload)});await loadInvoiceArticleCatalog(result.id);const article=articleCatalog.find(item=>String(item.id)===String(result.id));if(quickArticleTarget&&article){quickArticleTarget.querySelector('[data-article-select]').value=String(result.id);applyArticleToRow(quickArticleTarget,article);}await loadArticles();close();}catch(error){message.className='form-message error';message.textContent=[error.message,...(error.details||[])].join(' ');}finally{button.disabled=false;}});}
function setupPosAvailability(){for(const form of [document.querySelector('#article-form'),document.querySelector('#quick-article-form')]){const field=document.createElement('div');field.className='field wide pos-availability';field.innerHTML='<label class="check-option"><input name="availableInPos" type="checkbox"><span><strong>Disponible en POS</strong><small>Mostrar este producto o servicio en el punto de venta.</small></span></label>';const status=form.elements.status,anchor=status?.closest('.field');if(anchor)anchor.after(field);else form.querySelector('.form-grid').append(field);}}
const posCart=new Map();let posProducts=[],posFilter='';
async function loadPosProducts(){const search=document.querySelector('#pos-search').value;const {articles}=await request(`/api/articles?pos=true&type=${posFilter}&search=${encodeURIComponent(search)}`);posProducts=articles;document.querySelector('#pos-item-count').textContent=articles.length;const host=document.querySelector('#pos-products');host.innerHTML=articles.length?articles.map(a=>`<button class="pos-product" type="button" data-pos-article="${a.id}"><span class="pos-product-type">${a.itemType==='service'?'Servicio':'Producto'}</span><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.sku||a.unit||'')}</small><span class="pos-product-price">B/. ${Number(a.salePrice).toFixed(2)}</span></button>`).join(''):'<div class="pos-cart-empty wide">No hay artículos disponibles en POS con este filtro.</div>';host.querySelectorAll('[data-pos-article]').forEach(button=>button.addEventListener('click',()=>{const article=posProducts.find(a=>String(a.id)===button.dataset.posArticle),current=posCart.get(article.id);posCart.set(article.id,{article,quantity:(current?.quantity||0)+1});renderPosCart();}));}
async function loadPosClients(){const {clients}=await request('/api/clients');document.querySelector('#pos-client').innerHTML='<option value="">Consumidor final</option>'+clients.map(c=>`<option value="${c.id}">${escapeHtml(c.legalName)}${c.ruc?` · ${escapeHtml(c.ruc)}`:''}</option>`).join('');}
function posTotals(){let subtotal=0,tax=0;for(const {article,quantity} of posCart.values()){const net=Number(article.salePrice)*quantity;subtotal+=net;tax+=net*(taxRates[article.taxCode]||0);}return{subtotal:Math.round(subtotal*100)/100,tax:Math.round(tax*100)/100};}
function renderPosCart(){const host=document.querySelector('#pos-cart-items');host.innerHTML=posCart.size?[...posCart.values()].map(({article,quantity})=>{const total=Number(article.salePrice)*quantity*(1+(taxRates[article.taxCode]||0));return `<div class="pos-cart-row" data-pos-row="${article.id}"><div><strong>${escapeHtml(article.name)}</strong><small>B/. ${Number(article.salePrice).toFixed(2)} · ITBMS ${Math.round((taxRates[article.taxCode]||0)*100)}%</small></div><div class="pos-quantity"><button type="button" data-pos-minus>−</button><span>${quantity}</span><button type="button" data-pos-plus>+</button></div><span class="pos-line-total">B/. ${total.toFixed(2)}</span></div>`;}).join(''):'<div class="pos-cart-empty">Agrega un artículo para comenzar.</div>';host.querySelectorAll('[data-pos-row]').forEach(row=>{const id=Number(row.dataset.posRow);row.querySelector('[data-pos-minus]').addEventListener('click',()=>{const item=posCart.get(id);if(item.quantity<=1)posCart.delete(id);else item.quantity-=1;renderPosCart();});row.querySelector('[data-pos-plus]').addEventListener('click',()=>{posCart.get(id).quantity+=1;renderPosCart();});});const totals=posTotals();document.querySelector('#pos-subtotal').textContent=`B/. ${totals.subtotal.toFixed(2)}`;document.querySelector('#pos-tax').textContent=`B/. ${totals.tax.toFixed(2)}`;document.querySelector('#pos-total').textContent=`B/. ${(totals.subtotal+totals.tax).toFixed(2)}`;document.querySelector('#pos-checkout').disabled=!posCart.size;}
async function posCustomerPayload(){const id=document.querySelector('#pos-client').value;if(!id)return{customerType:'02',customerName:'Consumidor final',countryCode:'PA'};const {client}=await request(`/api/clients/${id}`);return{clientId:id,customerType:client.customerType,contributorType:client.contributorType,ruc:client.ruc,dv:client.dv,customerName:client.legalName,customerEmail:client.email,phone:client.phone,address:client.address,locationCode:client.locationCode,province:client.province,district:client.district,township:client.township,countryCode:client.countryCode,countryOther:client.countryOther,foreignIdType:client.foreignIdType,foreignIdNumber:client.foreignIdNumber,foreignCountry:client.foreignCountry};}
let posIdempotencyKey='',posIntentFingerprint='';
function setupPos(){document.querySelector('#pos-search').addEventListener('input',()=>loadPosProducts().catch(()=>{}));document.querySelectorAll('[data-pos-filter]').forEach(button=>button.addEventListener('click',()=>{posFilter=button.dataset.posFilter;document.querySelectorAll('[data-pos-filter]').forEach(item=>item.classList.toggle('active',item===button));loadPosProducts();}));document.querySelector('#clear-pos-cart').addEventListener('click',()=>{posCart.clear();posIdempotencyKey='';posIntentFingerprint='';renderPosCart();});document.querySelector('#pos-checkout').addEventListener('click',async event=>{const button=event.currentTarget,message=document.querySelector('#pos-message');if(!posCart.size)return;button.disabled=true;message.className='form-message';message.textContent='Procesando venta…';try{const customer=await posCustomerPayload(),payload={...customer,paymentMethod:document.querySelector('#pos-payment').value,items:[...posCart.values()].map(({article,quantity})=>({articleId:article.id,description:article.description||article.name,code:article.sku||'',quantity,unitPrice:article.salePrice,taxCode:article.taxCode}))},fingerprint=JSON.stringify(payload);if(!posIdempotencyKey||posIntentFingerprint!==fingerprint){posIdempotencyKey=crypto.randomUUID();posIntentFingerprint=fingerprint;}const data=await request('/api/invoices',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken,'idempotency-key':posIdempotencyKey},body:fingerprint});message.className='form-message success';message.textContent=`Venta autorizada. Factura N.º ${data.invoice.fiscalNumber}`;posCart.clear();posIdempotencyKey='';posIntentFingerprint='';renderPosCart();await loadInvoices();}catch(error){if(error.status==='rejected'||error.code==='IDEMPOTENCY_CONFLICT'){posIdempotencyKey='';posIntentFingerprint='';}message.className='form-message error';message.textContent=[error.message,...(error.details||[])].join(' ');}finally{button.disabled=!posCart.size;}});renderPosCart();}
function setupPosEnhancements(){const payment=document.querySelector('#pos-payment'),summary=document.querySelector('.pos-summary'),field=document.createElement('div'),cart=document.querySelector('.pos-cart'),catalog=document.querySelector('.pos-catalog');field.className='field pos-cash-field';field.innerHTML='<label for="pos-cash-received">Monto recibido</label><input id="pos-cash-received" type="number" min="0" step="0.01" inputmode="decimal" placeholder="B/. 0.00"><small>Cambio: <strong id="pos-change">B/. 0.00</strong></small>';summary.before(field);const received=field.querySelector('input'),change=field.querySelector('#pos-change'),heading=document.querySelector('.pos-cart-heading h2');function update(){const cash=payment.value==='02';field.hidden=!cash;if(!posCart.size&&received.value)received.value='';const total=posTotals(),due=total.subtotal+total.tax,tendered=Number(received.value)||0;change.textContent=`B/. ${Math.max(0,tendered-due).toFixed(2)}`;change.classList.toggle('insufficient',cash&&tendered>0&&tendered<due);heading.textContent=`Carrito · ${posCart.size} ${posCart.size===1?'línea':'líneas'}`;}function fit(){if(window.innerWidth<=1100){cart.style.height='';catalog.style.minHeight='';return;}const height=Math.max(520,window.innerHeight-cart.getBoundingClientRect().top-18);cart.style.height=`${height}px`;catalog.style.minHeight=`${height}px`;}payment.addEventListener('change',update);received.addEventListener('input',update);window.addEventListener('resize',fit);new MutationObserver(update).observe(document.querySelector('#pos-total'),{childList:true,characterData:true,subtree:true});document.querySelector('#pos-checkout').addEventListener('click',(event)=>{const due=posTotals().subtotal+posTotals().tax;if(payment.value==='02'&&(Number(received.value)||0)<due){event.stopImmediatePropagation();const message=document.querySelector('#pos-message');message.className='form-message error';message.textContent='El monto recibido debe cubrir el total de la venta.';received.focus();}},true);fit();update();}
function preserveCashCartLines(){const cart=document.querySelector('.pos-cart'),payment=document.querySelector('#pos-payment');function apply(){const cash=payment.value==='02';cart.classList.toggle('cash-payment',cash);if(window.innerWidth<=1100){cart.style.height='';return;}if(cash){cart.style.height='auto';return;}cart.style.height=`${Math.max(520,window.innerHeight-cart.getBoundingClientRect().top-18)}px`;}payment.addEventListener('change',apply);window.addEventListener('resize',apply);apply();}
function adminMessage(form,type,message){const node=form.querySelector('.form-message');node.className=`form-message ${type||''}`;node.textContent=message;}
async function loadAdministration(){const [companyData,memberData]=await Promise.all([request('/api/administration/companies'),request('/api/administration/memberships')]);document.querySelector('#company-count').textContent=companyData.companies.length;document.querySelector('#membership-count').textContent=memberData.memberships.length;document.querySelector('#membership-company-name').textContent=memberData.company.name;document.querySelector('#company-admin-list').innerHTML=companyData.companies.length?companyData.companies.map(company=>`<div class="company-admin-row ${Number(company.id)===Number(companyData.activeCompanyId)?'active':''}"><div><strong>${escapeHtml(company.tradeName||company.legalName)}</strong><span>${escapeHtml(company.ruc?`RUC ${company.ruc}${company.dv?`-${company.dv}`:''}`:'Sin identificación fiscal')} · ${company.activeMembers} miembros activos</span></div>${Number(company.id)===Number(companyData.activeCompanyId)?'<b>Activa</b>':''}</div>`).join(''):'<div class="admin-empty">No hay empresas registradas.</div>';const roles={administrator:'Administrador',accountant:'Contador',operator:'Operador'},statuses={active:'Activo',suspended:'Suspendido'},host=document.querySelector('#membership-list');host.innerHTML=memberData.memberships.length?memberData.memberships.map(member=>`<div class="membership-row" data-membership-user="${member.userId}"><div><strong>${escapeHtml(member.fullName)}</strong><span>${escapeHtml(member.email)}</span></div><select data-membership-role>${Object.entries(roles).map(([value,label])=>`<option value="${value}" ${member.role===value?'selected':''}>${label}</option>`).join('')}</select><select data-membership-status>${Object.entries(statuses).map(([value,label])=>`<option value="${value}" ${member.status===value?'selected':''}>${label}</option>`).join('')}</select><button class="small-button" type="button" data-save-membership>Guardar</button></div>`).join(''):'<div class="admin-empty">No hay membresías.</div>';host.querySelectorAll('[data-save-membership]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('[data-membership-user]');button.disabled=true;try{await request(`/api/administration/memberships/${row.dataset.membershipUser}`,{method:'PUT',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify({role:row.querySelector('[data-membership-role]').value,status:row.querySelector('[data-membership-status]').value})});location.reload();}catch(error){button.disabled=false;alert(error.message);}}));}
function setupAdministration(){const companyForm=document.querySelector('#company-form'),membershipForm=document.querySelector('#membership-form');companyForm.addEventListener('submit',async event=>{event.preventDefault();const button=companyForm.querySelector('[type="submit"]');button.disabled=true;try{const result=await request('/api/administration/companies',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(Object.fromEntries(new FormData(companyForm)))});adminMessage(companyForm,'success',result.message);companyForm.reset();setTimeout(()=>location.reload(),700);}catch(error){adminMessage(companyForm,'error',[error.message,...(error.details||[])].join(' '));button.disabled=false;}});membershipForm.addEventListener('submit',async event=>{event.preventDefault();const button=membershipForm.querySelector('[type="submit"]');button.disabled=true;try{const result=await request('/api/administration/memberships',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(Object.fromEntries(new FormData(membershipForm)))});adminMessage(membershipForm,'success',result.message);membershipForm.reset();await loadAdministration();}catch(error){adminMessage(membershipForm,'error',[error.message,...(error.details||[])].join(' '));}finally{button.disabled=false;}});}
async function runUserAdminAction(action){try{return await action();}catch(error){if(error.code!=='MFA_RECENT_REQUIRED')throw error;const code=prompt('Introduce tu código MFA actual para autorizar esta operación:');if(!/^\d{6}$/.test(code||''))throw new Error('Se requiere un código MFA válido.');await stepUpMfa(code);return action();}}
async function loadUsers(){const {users}=await request('/api/users');document.querySelector('#user-admin-count').textContent=users.length;const roles={administrator:'Administrador',accountant:'Contador',operator:'Operador'},statuses={active:'Activo',suspended:'Suspendido'},host=document.querySelector('#user-admin-list');host.innerHTML=users.length?users.map(user=>`<div class="managed-user" data-managed-user="${user.id}"><div class="managed-user-head"><div><strong>${escapeHtml(user.fullName)}</strong><span>${escapeHtml(user.email)}</span></div><span class="status ${user.accountStatus==='pending'?'status-uncertain':user.accessStatus==='active'?'status-authorized':'status-rejected'}">${user.accountStatus==='pending'?'Pendiente':statuses[user.accessStatus]}</span></div><div class="form-grid"><div class="field"><label>Nombre</label><input data-user-name value="${escapeHtml(user.fullName)}" maxlength="120"></div><div class="field"><label>Correo</label><input data-user-email type="email" value="${escapeHtml(user.email)}" maxlength="254"></div><div class="field"><label>Rol</label><select data-user-role>${Object.entries(roles).map(([value,label])=>`<option value="${value}" ${user.role===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Acceso</label><select data-user-status><option value="active" ${user.accessStatus==='active'?'selected':''}>Activo</option><option value="suspended" ${user.accessStatus==='suspended'?'selected':''}>Suspendido</option></select></div></div><div class="managed-user-actions"><button class="small-button" type="button" data-revoke-user>Revocar sesiones</button><button class="small-button" type="button" data-save-user>Guardar cambios</button></div></div>`).join(''):'<div class="admin-empty">No hay usuarios asociados.</div>';host.querySelectorAll('[data-save-user]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('[data-managed-user]');button.disabled=true;try{await runUserAdminAction(()=>request(`/api/users/${row.dataset.managedUser}`,{method:'PUT',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify({fullName:row.querySelector('[data-user-name]').value,email:row.querySelector('[data-user-email]').value,role:row.querySelector('[data-user-role]').value,status:row.querySelector('[data-user-status]').value})}));await loadUsers();}catch(error){alert(error.message);}finally{button.disabled=false;}}));host.querySelectorAll('[data-revoke-user]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('[data-managed-user]');button.disabled=true;try{await runUserAdminAction(()=>request(`/api/users/${row.dataset.managedUser}/revoke-sessions`,{method:'POST',headers:{'x-csrf-token':csrfToken}}));alert('Sesiones revocadas.');}catch(error){alert(error.message);}finally{button.disabled=false;}}));}
function setupUsers(){const form=document.querySelector('#user-invite-form'),result=document.querySelector('#invitation-result'),url=document.querySelector('#invitation-url');form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type="submit"]'),message=form.querySelector('.form-message');button.disabled=true;result.hidden=true;try{const data=await runUserAdminAction(()=>request('/api/users/invite',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(Object.fromEntries(new FormData(form)))}));message.className='form-message success';message.textContent=data.message;if(data.invitationUrl){url.value=data.invitationUrl;result.hidden=false;}form.reset();await loadUsers();}catch(error){message.className='form-message error';message.textContent=[error.message,...(error.details||[])].join(' ');}finally{button.disabled=false;}});document.querySelector('#copy-invitation').addEventListener('click',async()=>{await navigator.clipboard.writeText(url.value);document.querySelector('#copy-invitation').textContent='Copiado';});}
const sectionLabels = { erpDashboard:['Operación','Resumen ERP'],quotations:['Ventas','Cotizaciones'],orders:['Ventas','Pedidos'],receivables:['Finanzas','Cobros'],invoice: ['Operación', 'Nueva factura'], pos: ['Punto de venta', 'Venta rápida'], documents: ['Trazabilidad', 'Facturas'], clients: ['Directorio comercial', 'Clientes'], articles: ['Catálogo comercial', 'Artículos'], crm: ['Relaciones', 'CRM'], configuration: ['Administración', 'Configuración'], administration: ['Administración', 'Empresas y acceso'], users: ['Administración', 'Usuarios'] };
function importFormData(confirm = false) { const data = new FormData(); const file = document.querySelector('#zoho-file').files[0]; if (file) data.append('file', file); if (confirm) data.append('confirm', 'true'); return data; }
function importPreviewMarkup(data) { const s = data.summary; const rows = data.preview.map((row) => `<div class="import-row"><span>Fila ${row.row}</span><strong>${escapeHtml(row.name)}</strong><span>${row.warnings.length ? escapeHtml(row.warnings.join(' ')) : 'Lista'}</span></div>`).join(''); return `<div class="import-summary"><div><strong>${s.total}</strong><span>Total</span></div><div><strong>${s.ready}</strong><span>Listos</span></div><div><strong>${s.duplicates}</strong><span>Duplicados</span></div><div><strong>${s.invalid}</strong><span>Inválidos</span></div></div><div class="import-rows">${rows || '<div class="import-row"><span>—</span><strong>No hay filas listas para importar</strong><span>Revisa el archivo</span></div>'}</div>`; }
function setupZohoImport() { const dialog = document.querySelector('#zoho-import-dialog'); const form = document.querySelector('#zoho-import-form'); const message = document.querySelector('#import-message'); const confirm = document.querySelector('#confirm-import'); const close = () => { dialog.close(); form.reset(); document.querySelector('#import-preview').innerHTML = ''; confirm.hidden = true; message.textContent = ''; }; document.querySelector('#import-clients').addEventListener('click', () => dialog.showModal()); document.querySelector('#close-import').addEventListener('click', close); document.querySelector('#cancel-import').addEventListener('click', close); form.addEventListener('submit', async (event) => { event.preventDefault(); if (!form.reportValidity()) return; message.className = 'form-message'; message.textContent = 'Analizando archivo…'; try { const data = await request('/api/clients/import/zoho', { method: 'POST', headers: { 'x-csrf-token': csrfToken }, body: importFormData() }); document.querySelector('#import-preview').innerHTML = importPreviewMarkup(data); confirm.hidden = data.summary.ready === 0; message.textContent = `${data.summary.ready} filas listas. ${data.summary.duplicates} duplicadas y ${data.summary.invalid} inválidas serán omitidas.`; } catch (error) { message.className = 'form-message error'; message.textContent = error.message; } }); confirm.addEventListener('click', async () => { confirm.disabled = true; try { const data = await request('/api/clients/import/zoho', { method: 'POST', headers: { 'x-csrf-token': csrfToken }, body: importFormData(true) }); message.className = 'form-message success'; message.textContent = data.message; confirm.hidden = true; await loadClients(); } catch (error) { message.className = 'form-message error'; message.textContent = error.message; } finally { confirm.disabled = false; } }); }
function navigate(section, updateHash = true) { const panel = document.querySelector(`[data-panel="${section}"]`),erpSections=['erpDashboard','quotations','orders','invoice','documents','pos','clients','articles','receivables'],adminSections=['configuration','administration','users'],area=erpSections.includes(section)?'erp':adminSections.includes(section)?'administration':'crm',link=document.querySelector(`[data-section="${section}"]`); if (!panel || !link || link.hidden) return navigate(document.querySelector('[data-panel="erpDashboard"]')?'erpDashboard':'invoice', updateHash); document.querySelectorAll('.app-section').forEach((item) => { item.hidden = item !== panel; item.classList.toggle('active', item === panel); }); document.querySelectorAll('[data-area-navigation]').forEach(nav=>{nav.hidden=nav.dataset.areaNavigation!==area;});document.querySelectorAll('[data-area-navigation] [data-section]').forEach(item=>{const active=item.dataset.section===section;item.classList.toggle('active',active);if(active)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current');});document.querySelectorAll('.nav-module-link').forEach(item=>{const active=item.dataset.module===area;item.classList.toggle('active',active);if(active)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current');}); const [eyebrow, title] = sectionLabels[section]; document.querySelector('#section-eyebrow').textContent = eyebrow; document.querySelector('#section-title').textContent = title; if (section==='crm'&&typeof loadCrm==='function') loadCrm(); if (typeof loadErpSection==='function'&&erpSections.includes(section))loadErpSection(section); if (updateHash) history.replaceState(null, '', `#${section}`); closeMenu(); }
function closeMenu() { document.querySelector('#app-sidebar').classList.remove('open'); document.querySelector('#sidebar-overlay').classList.remove('visible'); document.querySelector('#menu-toggle').setAttribute('aria-expanded', 'false'); }
function setupNavigation() { document.querySelectorAll('[data-section]').forEach((button) => button.addEventListener('click', () => navigate(button.dataset.section))); document.querySelectorAll('[data-module-toggle]').forEach((button)=>button.addEventListener('click',()=>{const group=button.closest('[data-nav-group]'),open=group.classList.toggle('open');button.setAttribute('aria-expanded',String(open));})); document.querySelectorAll('[data-navigation]').forEach((link) => link.addEventListener('click', (event) => { event.preventDefault(); navigate(link.dataset.navigation); })); document.querySelector('#menu-toggle').addEventListener('click', () => { const sidebar = document.querySelector('#app-sidebar'); const open = sidebar.classList.toggle('open'); document.querySelector('#sidebar-overlay').classList.toggle('visible', open); document.querySelector('#menu-toggle').setAttribute('aria-expanded', String(open)); }); document.querySelector('#sidebar-overlay').addEventListener('click', closeMenu); document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeMenu(); }); }
async function setupCompanySwitcher() { const data=await request('/api/auth/companies'),select=document.querySelector('#active-company');select.innerHTML=data.companies.map(company=>`<option value="${company.id}">${escapeHtml(company.tradeName||company.legalName)}</option>`).join('');select.value=String(data.activeCompanyId);select.disabled=data.companies.length<2;select.addEventListener('change',async()=>{select.disabled=true;try{await request('/api/auth/company',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify({companyId:Number(select.value)})});location.reload();}catch(error){select.disabled=false;alert(error.message);}});}
async function load() { try { const [session, csrf] = await Promise.all([request('/api/auth/me'), request('/api/csrf-token')]); csrfToken = csrf.csrfToken; document.querySelector('#user-name').textContent = session.user.fullName; document.querySelector('#sidebar-user-name').textContent = session.user.fullName; document.querySelector('#user-initials').textContent = session.user.fullName.split(/\s+/).slice(0, 2).map((word) => word[0]).join('').toUpperCase(); document.querySelector('#user-email').textContent = session.user.email; document.querySelector('#user-role').textContent = session.user.role; await setupCompanySwitcher(); if (session.user.role === 'administrator') { document.querySelectorAll('.admin-navigation').forEach((element) => { element.hidden = false; }); setupAdministration(); await Promise.all([mountConfiguration(),loadAdministration()]); } await loadInvoices(); navigate(location.hash.slice(1) || 'erpDashboard', false); } catch { window.location.replace('/login.html'); } }
